#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h>
#include <zephyr/sys/atomic.h>

/*
 * @brief Test for Zephyr Message Box (mbox) API usage.
 *
 * This test suite verifies the basic functionality of the Zephyr message box,
 * including thread-to-thread communication and ISR-to-thread communication.
 */

/* Define stack size for test threads */
#define STACK_SIZE 512

/* Define message size for mbox messages */
#define MSG_SIZE 4

/* Global kernel objects for thread-to-thread communication */
static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tdata;
static struct k_mbox mbox;

/* Message buffers for thread-to-thread tests */
static char tx_msg[MSG_SIZE];
static char rx_msg[MSG_SIZE];

/**
 * @brief Setup function for the mbox test suite.
 *
 * Initializes the global message box before each test case.
 *
 * @return NULL (no fixture data).
 */
static void *mbox_setup(void)
{
    /* Initialize global mbox for thread-to-thread tests */
    k_mbox_init(&mbox);
    return NULL;
}









































/**
 * @brief Teardown function for the mbox test suite.
 *
 * Currently, no specific teardown is needed for the message box.
 *
 * @param data Unused fixture data.
 */
static void mbox_teardown(void *data)
{
    /* No specific teardown needed for mbox */
    ARG_UNUSED(data);
}


/**
 * @brief Entry point for a sender thread.
 *
 * This thread initializes a message structure and puts the message
 * into the global message box, blocking indefinitely until the message
 * is successfully sent.
 *
 * @param p1 Unused.
 * @param p2 Unused.
 * @param p3 Unused.
 */
static void sender_thread_entry(void *p1, void *p2, void *p3)
{
    struct k_mbox_msg msg;

    /* Initialize message fields */
    msg.info = 0x1234; /* Arbitrary message info */
    msg.size = MSG_SIZE; /* Size of the message data */
    msg.tx_data = tx_msg; /* Pointer to the transmit data buffer */
    msg.tx_block = K_FOREVER; /* Block indefinitely until message is sent */

    /* Put the message into the message box */
    k_mbox_put(&mbox, &msg, K_FOREVER);
}

/**
 * @brief Entry point for a receiver thread.
 *
 * This thread initializes a message structure for reception and gets
 * a message from the global message box, blocking indefinitely until
 * a message is received. It then asserts the content of the received
 * message.
 *
 * @param p1 Unused.
 * @param p2 Unused.
 * @param p3 Unused.
 */
static void receiver_thread_entry(void *p1, void *p2, void *p3)
{
    struct k_mbox_msg msg;

    /* Initialize message fields for reception */
    msg.rx_data = rx_msg; /* Pointer to the receive data buffer */
    msg.size = MSG_SIZE; /* Expected size of the message data */

    /* Get a message from the message box */
    k_mbox_get(&mbox, &msg, K_FOREVER);

    /* Assert the received message content */
    zassert_equal(msg.info, 0x1234, "Incorrect message info received");
    zassert_equal(msg.size, MSG_SIZE, "Incorrect message size received");
    zassert_mem_equal(rx_msg, tx_msg, MSG_SIZE, "Incorrect message data received");
}

ZTEST_F_SUITE(mbox_usage, mbox_setup, mbox_teardown, NULL, NULL, NULL);

/**
 * @brief Test case: Thread to Thread communication using k_mbox_put/get.
 *
 * This test verifies that a message can be successfully sent from one thread
 * to another using the Zephyr message box API. It involves creating a sender
 * thread and a receiver thread, and then waiting for the threads to complete
 * their operations.
 */
ZTEST_TEST(mbox_usage, test_mbox_thread_to_thread)
{
    k_thread_create(&tdata, tstack, STACK_SIZE,
                    sender_thread_entry, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(5), 0, K_NO_WAIT);

    k_thread_create(&tdata, tstack, STACK_SIZE,
                    receiver_thread_entry, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(5), 0, K_NO_WAIT);

    k_thread_join(&tdata, K_FOREVER);
}

ZTEST_SUITE(mbox_usage, NULL, NULL, NULL, NULL, NULL);
